def check_symmetry():
    p = 61
    A = [0] * p
    for a in range(p):
        A[(a**2) % p] += 1

    f = [0] * p
    for i in range(p):
        for j in range(p):
            f[(i + j) % p] += A[i] * A[j]

    is_symmetric = True
    for x in range(1, p):
        if f[x] != f[p - x]:
            is_symmetric = False
            break
    return is_symmetric, f

