def solve():
    p = 61
    A = [0] * p
    for a in range(p):
        A[(a**2) % p] += 1

    B = [0] * p
    for c in range(p):
        B[(c**3) % p] += 1

    f = [0] * p
    for i in range(p):
        if A[i] == 0: continue
        for j in range(p):
            if A[j] == 0: continue
            f[(i + j) % p] += A[i] * A[j]

    g = [0] * p
    for k in range(p):
        if B[k] == 0: continue
        for l in range(p):
            if B[l] == 0: continue
            g[(k - l) % p] += B[k] * B[l]

    ans = sum(f[x] * g[x] for x in range(p))
    return ans

print(solve())

